<template>
  <section class="budget-panel" aria-label="共享预算与准入">
    <ConsolePageHeader description="普通任务、工作流和提示词实验共用部署额度，可按智能体、任务或实验进一步限制。"><template #actions><el-button :loading="loading" :disabled="busy" @click="load">刷新预算</el-button><el-button v-if="permissions.can('manageBudgets')" type="primary" :disabled="loading||busy" @click="open()">设置范围预算</el-button></template></ConsolePageHeader>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-alert v-if="!data.enabled" title="预算拦截尚未启用，配置限额不会约束执行。" type="warning" :closable="false" />
    <div class="budget-cards"><article v-for="unit in unitKeys" :key="unit"><span>{{ units[unit] }} · 部署共享</span><strong>{{ global(unit)?number(global(unit)!.usedAmount):'—' }}</strong><small>已用 / 已承诺</small><p>在途预留 <b>{{ global(unit)?number(global(unit)!.reservedAmount):'—' }}</b></p><p>{{ global(unit)?.limitAmount==null?'未设置上限':`额度 ${number(global(unit)!.limitAmount!)}` }}</p></article></div>
    <el-card shadow="never" class="panel"><template #header><strong>范围额度 · 已用＋在途预留＋安全余量</strong></template>
      <div class="budget-account-list"><article v-for="a in data.accounts" :key="a.id" class="budget-account"><div class="budget-account-title"><strong>{{ scopes[a.scopeType] }} {{ scopeName(a) }} · {{ units[a.unit] }}</strong><el-tag :type="a.violated?'danger':remaining(a)===0?'warning':'info'">{{ a.violated?'上界违例，停止准入':a.limitAmount==null?'未设上限':remaining(a)===0?'额度不足':'限额生效' }}</el-tag></div><div class="budget-numbers"><span>已用 <b>{{ number(a.usedAmount) }}</b></span><span>在途 <b>{{ number(a.reservedAmount) }}</b></span><span>余量 <b>{{ number(a.marginAmount) }}</b></span><span>上限 <b>{{ a.limitAmount==null?'未设置':number(a.limitAmount) }}</b></span><span>可预留 <b>{{ remaining(a)==null?'未限定':number(remaining(a)!) }}</b></span></div><el-progress v-if="a.limitAmount!=null" :percentage="percent(a)" :status="a.violated?'exception':undefined" :show-text="false" /><div class="budget-account-footer"><small>配置版本 {{ a.revision }} · {{ time(a.updatedAt) }}</small><el-button v-if="permissions.can('manageBudgets')" text :disabled="busy" @click="open(a)">调整额度</el-button></div></article></div>
    </el-card>
    <el-card shadow="never" class="panel"><template #header><strong>最近执行意图与结算 · 100 条以内</strong></template><el-table :data="data.reservations" max-height="480" row-key="id"><el-table-column label="范围 / 关联" min-width="190"><template #default="{row}"><strong>{{ row.agentId?`智能体 #${row.agentId}`:'网络端点' }}</strong><small class="budget-meta" v-if="row.taskKey">任务 {{ row.taskKey }}</small><small class="budget-meta" v-if="row.experimentId">实验 #{{ row.experimentId }}</small><small class="budget-meta" :title="row.traceId">{{ row.traceId }}</small></template></el-table-column><el-table-column label="执行意图" width="135"><template #default="{row}">{{ row.operation==='MODEL'?'模型派发':'工具许可' }}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.state==='UNKNOWN'||row.state==='VIOLATION'?'warning':'info'">{{ states[row.state]||row.state }}</el-tag></template></el-table-column><el-table-column label="声明 / 实际输出" min-width="150"><template #default="{row}">{{ row.operation==='MODEL'?`${row.outputBound} / ${row.outputTokens==null?'未知':number(row.outputTokens)} Token`:'1 次许可' }}</template></el-table-column><el-table-column label="记录时间" width="175"><template #default="{row}">{{ time(row.createdAt) }}</template></el-table-column></el-table><el-empty v-if="!data.reservations.length&&!loading" description="尚无预算账本记录，启用后从新的受管请求开始累计" /></el-card>
    <p class="budget-note">输出 Token 预留不含输入 Token，也不是账单金额。响应丢失或用量缺失会保留输出占用；已保存的调用意图不自动重放。没有跨日重置、自动释放未知记录或人工解除入口。旧客户端缺少任务标识时仍扣部署及智能体预算。</p>
    <el-dialog v-model="dialog" title="设置预算上限" width="min(580px, calc(100vw - 28px))" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
      <el-alert v-if="uncertain" title="修改结果尚未确认，请刷新核对当前配置；不会自动重试或清零账本。" type="warning" :closable="false" />
      <el-form label-position="top" @submit.prevent="save">
        <el-form-item label="预算范围"><el-select v-model="draft.scopeType" :disabled="busy||locked||uncertain" @change="scopeChanged"><el-option v-for="(label,key) in scopes" :key="key" :label="label" :value="key" /></el-select></el-form-item>
        <el-form-item label="范围标识"><el-select v-if="draft.scopeType==='AGENT'&&!locked" v-model="draft.scopeKey" filterable :disabled="busy||uncertain" placeholder="选择实际智能体" @change="revision"><el-option v-for="a in agents" :key="a.id" :label="`${a.name} · #${a.id}`" :value="String(a.id)" /></el-select><el-input v-else v-model="draft.scopeKey" :disabled="busy||locked||uncertain||draft.scopeType==='PLATFORM'" :maxlength="128" placeholder="实验 ID 或已有任务标识" @change="revision" /></el-form-item>
        <el-form-item label="计量单位"><el-select v-model="draft.unit" :disabled="busy||locked||uncertain" @change="revision"><el-option v-for="(label,key) in units" :key="key" :label="label" :value="key" /></el-select></el-form-item>
        <el-form-item label="额度"><el-switch v-model="unlimited" :disabled="busy||uncertain" active-text="不设置上限" /><el-input-number v-if="!unlimited" v-model="draft.limitAmount" :min="0" :max="1000000000000" :precision="0" :disabled="busy||uncertain" aria-label="预算额度" /></el-form-item>
        <el-form-item label="安全余量"><el-input-number v-model="draft.marginAmount" :min="0" :max="1000000000000" :precision="0" :disabled="busy||uncertain" aria-label="预算安全余量" /></el-form-item>
        <p class="budget-note">调小上限不会改变已用或在途占用；已发生的上界违例不能通过修改上限抹去。配置采用版本比较更新。</p><div class="budget-actions"><el-button :disabled="busy" @click="dialog=false">关闭</el-button><el-button v-if="uncertain" :disabled="busy" @click="verify">刷新核对</el-button><el-button v-else type="primary" native-type="submit" :loading="busy">保存额度</el-button></div>
      </el-form>
    </el-dialog>
  </section>
</template>
<script setup lang="ts">
import ConsolePageHeader from '@/components/common/ConsolePageHeader.vue'
import {ref,watch,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {BudgetApi} from '@/api/budgets'
import type {BudgetAccount,BudgetDashboard,BudgetLimit,BudgetUnit} from '@/api/budgets'
import {EapApi} from '@/api/eap'
import type {Agent} from '@/types/domain'
import {usePermissions} from '@/stores/permissions'
const permissions=usePermissions(),data=ref<BudgetDashboard>({enabled:false,accounts:[],reservations:[]}),agents=ref<Agent[]>([]),loading=ref(false),busy=ref(false),dialog=ref(false),locked=ref(false),uncertain=ref(false),unlimited=ref(false),error=ref('')
const units={MODEL_CALLS:'模型派发次数',OUTPUT_TOKENS:'输出 Token',TOOL_CLAIMS:'工具许可次数'},unitKeys=Object.keys(units) as BudgetUnit[]
const scopes={PLATFORM:'部署共享',AGENT:'智能体',TASK:'任务',EXPERIMENT:'实验'},states:Record<string,string>={DISPATCHED:'在途 / 意图已存',SETTLED:'已结算',UNKNOWN:'未知，保留占用',VIOLATION:'上界违例'}
const draft=ref<BudgetLimit>({scopeType:'AGENT',scopeKey:'',unit:'MODEL_CALLS',limitAmount:0,marginAmount:0,expectedRevision:0})
let generation=0,alive=true
function current(run:number,user:unknown){return alive&&run===generation&&user===permissions.state.user&&permissions.can('viewConsole')}
async function load(){if(busy.value||!permissions.can('viewConsole'))return;const run=++generation,user=permissions.state.user;loading.value=true;error.value='';try{const [d,a]=await Promise.all([BudgetApi.get(),EapApi.listAgents()]);if(current(run,user)){data.value=d;agents.value=a}}catch{if(current(run,user))error.value='预算记录读取失败，请刷新重试。'}finally{if(current(run,user))loading.value=false}}
function global(unit:BudgetUnit){return data.value.accounts.find(a=>a.scopeType==='PLATFORM'&&a.unit===unit)}
function number(value:number){return new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(value)}
function time(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false})}
function scopeName(a:BudgetAccount){return a.scopeType==='PLATFORM'?'':a.scopeType==='AGENT'?(agents.value.find(x=>String(x.id)===a.scopeKey)?.name||`#${a.scopeKey}`):a.scopeKey}
function remaining(a:BudgetAccount){return a.limitAmount==null?null:Math.max(0,a.limitAmount-a.usedAmount-a.reservedAmount-a.marginAmount)}
function percent(a:BudgetAccount){return a.limitAmount==null?0:a.limitAmount===0?100:Math.min(100,Math.max(0,Math.round(100*(a.usedAmount+a.reservedAmount+a.marginAmount)/a.limitAmount)))}
function open(a?:BudgetAccount){if(!permissions.can('manageBudgets')||busy.value)return;locked.value=!!a;uncertain.value=false;draft.value=a?{scopeType:a.scopeType,scopeKey:a.scopeKey,unit:a.unit,limitAmount:a.limitAmount,marginAmount:a.marginAmount,expectedRevision:a.revision}:{scopeType:'AGENT',scopeKey:'',unit:'MODEL_CALLS',limitAmount:0,marginAmount:0,expectedRevision:0};unlimited.value=a?.limitAmount==null&&!!a;dialog.value=true}
function revision(){const a=data.value.accounts.find(a=>a.scopeType===draft.value.scopeType&&a.scopeKey===draft.value.scopeKey&&a.unit===draft.value.unit);draft.value.expectedRevision=a?.revision||0}
function scopeChanged(){draft.value.scopeKey=draft.value.scopeType==='PLATFORM'?'default':'';revision()}
async function save(){if(busy.value||uncertain.value||!permissions.can('manageBudgets'))return;const d=draft.value;if(!d.scopeKey.trim()||!Number.isSafeInteger(d.marginAmount)||d.marginAmount<0||d.marginAmount>1e12||!unlimited.value&&(d.limitAmount==null||!Number.isSafeInteger(d.limitAmount)||d.limitAmount<0||d.limitAmount>1e12)){ElMessage.warning('请选择实际范围并填写有效额度');return}const run=++generation,user=permissions.state.user;busy.value=true;try{await BudgetApi.set({...d,limitAmount:unlimited.value?null:d.limitAmount});if(current(run,user)){dialog.value=false;ElMessage.success('预算配置已保存，历史用量和预留保持')}}catch{if(current(run,user))uncertain.value=true}finally{if(current(run,user)){busy.value=false;void load()}}}
async function verify(){const user=permissions.state.user;await load();if(alive&&user===permissions.state.user&&permissions.can('manageBudgets')&&!loading.value&&!error.value){revision();uncertain.value=false}}
watch(()=>permissions.state.user,()=>{generation++;data.value={enabled:false,accounts:[],reservations:[]};agents.value=[];dialog.value=false;busy.value=false;loading.value=false;uncertain.value=false;if(permissions.can('viewConsole'))void load()},{immediate:true})
onBeforeUnmount(()=>{alive=false;generation++})
</script>
<style scoped>
.budget-panel{display:grid;gap:18px;min-width:0}.budget-account-title,.budget-account-footer{display:flex;justify-content:space-between;gap:16px;align-items:center}.budget-note{color:#61768b;font-size:13px;line-height:1.7}.budget-actions{display:flex;gap:10px;flex-wrap:wrap}.budget-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.budget-cards article{background:var(--console-surface);border:1px solid var(--console-line);border-radius:var(--console-radius);padding:20px;color:var(--console-ink)}.budget-cards strong{display:block;font-size:32px;margin-top:12px}.budget-cards span,.budget-cards small{color:var(--console-muted);font-size:13px}.budget-cards p{margin:10px 0 0;font-size:13px}.budget-account-list{display:grid;gap:14px}.budget-account{padding:18px;border:1px solid #d7e5f0;border-radius:var(--console-radius);background:var(--console-surface)}.budget-numbers{display:flex;gap:24px;flex-wrap:wrap;margin:16px 0;font-size:13px}.budget-numbers span{color:#5d748b}.budget-numbers b{color:#174263;margin-left:5px}.budget-account-footer{margin-top:10px;color:#61768b}.budget-meta{display:block;overflow-wrap:anywhere;font-size:12px;color:#627b91}.budget-panel :deep(.el-select){width:100%}.budget-panel :deep(.el-dialog__body){max-height:calc(100vh - 200px);overflow:auto}@media(max-width:720px){.budget-account-title{align-items:flex-start;flex-direction:column}.budget-cards{grid-template-columns:1fr}.budget-cards article{padding:18px}.budget-cards strong{font-size:26px}.budget-numbers{gap:12px}.budget-account-footer{align-items:flex-start}.budget-account{padding:14px}}
</style>
